def _validated_chain_policy(policy: object) -> dict:
    """Validate one versioned chain policy into a fresh normalized dict.

    Exactly 'sites', 'threshold' and 'version'... sites/threshold follow
    the convergence site policy rules; version is a positive non-bool int.
    """
    if not isinstance(policy, dict):
        raise TypeError("chain policy must be a dict")
    if set(policy.keys()) != _SC_POLICY_KEYS:
        raise ValueError("chain policy must contain exactly the keys 'sites', 'threshold' and 'version'")
    validated = _validated_convergence_site_policy({CD_SITES: policy[CD_SITES], CD_THRESHOLD: policy[CD_THRESHOLD]})
    version = policy[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("chain policy version must be an int")
    if version <= 0:
        raise ValueError("chain policy version must be a positive integer")
    validated[VERSION] = version
    return validated
