def _reject_duplicate_chain_keys(pairs): ... raise _chain_invalid(f"duplicate key {key!r} in object")

def _parse_chain_successor(raw: object) -> tuple[dict, str]:
    """Validate successor packet bytes into (payload, signature)."""
    if not isinstance(raw, bytes):
        raise TypeError("successor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _chain_invalid("must end with the closing brace, no trailing byte")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _chain_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(text, object_pairs_hook=_reject_duplicate_chain_keys)
    except json.JSONDecodeError as exc:
        raise _chain_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("successor must be a JSON object")
    if set(data.keys()) != _SC_TOP_KEYS:
        raise _chain_invalid("must contain exactly the keys 'payload' and 'signature'")
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("successor signature must be a str")
    if _HEX64.fullmatch(signature) is None:
        raise _chain_invalid("signature must be 64 lowercase hex characters")
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("successor payload must be an object")
    if set(payload.keys()) != _SC_PAYLOAD_KEYS:
        raise _chain_invalid("payload must contain exactly the keys 'decision', 'evidenceDelta', 'height', 'issuer', 'keyVersion', 'moment', 'policyDigest', 'predecessorDigest', 'previousPolicyDigest', 'rootDigest' and 'version'")
    ... field checks ...
    if _checkpoint_compact(data) != raw:
        raise _chain_invalid("encoding is not the canonical compact form")
    return payload, signature
