Core chain walk:

```python
def _verify_decision_chain_core(
    root: bytes,
    successors: list,
    validated_policies: list[dict],
    decision: bytes,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify the root and walk every successor hop; shared core."""
    root_result = _verify_convergence_decision(
        root, decision, _chain_site_policy(validated_policies[0]),
        validated_keyring, moment,
    )
    for index in range(1, len(validated_policies)):
        if not _chain_policy_step(validated_policies[index - 1], validated_policies[index]):
            raise _chain_invalid(
                f"policy {index} version does not follow the policy history rules"
            )
    root_digest = hashlib.sha256(root).hexdigest()
    previous_bytes = root
    previous_certificates = root_result[CD_CERTIFICATES]
    previous_status = root_result[STATUS]
    previous_common = root_result[CD_COMMON]
    previous_moment = None
    head_digest = root_digest
    status = previous_status
    for index, hop in enumerate(successors):
        height = index + 1
        where = f"successor {index}"
        payload, signature = _parse_chain_successor(hop)
        if payload[SC_ROOT_DIGEST] != root_digest:
            raise _chain_invalid(f"{where} root digest does not match the chain root")
        if payload[SC_PREDECESSOR_DIGEST] != hashlib.sha256(previous_bytes).hexdigest():
            raise _chain_invalid(f"{where} predecessor digest does not match the previous packet")
        if payload[SC_HEIGHT] != height:
            raise _chain_invalid(f"{where} height must be {height}")
        if payload[SC_PREVIOUS_POLICY_DIGEST] != _chain_policy_digest(validated_policies[index]):
            raise _chain_invalid(f"{where} previous policy digest does not match the policy history")
        if payload[CD_POLICY_DIGEST] != _chain_policy_digest(validated_policies[height]):
            raise _chain_invalid(f"{where} policy digest does not match the policy history")
        decision_bytes = _checkpoint_compact(payload[SC_DECISION])
        decision_result = _verify_convergence_decision(
            decision_bytes, decision, _chain_site_policy(validated_policies[height]),
            validated_keyring, moment,
        )
        certificates = decision_result[CD_CERTIFICATES]
        if certificates[:len(previous_certificates)] != previous_certificates:
            raise _chain_invalid(f"{where} evidence sequence must extend its predecessor")
        if payload[SC_EVIDENCE_DELTA] != certificates[len(previous_certificates):]:
            raise _chain_invalid(f"{where} evidence delta does not match the bound decision")
        new_status = decision_result[STATUS]
        new_common = decision_result[CD_COMMON]
        if previous_status == CD_STATUS_ACCEPTED:
            if new_status == CD_STATUS_ACCEPTED:
                if new_common != previous_common:
                    raise _chain_invalid(f"{where} must keep the accepted common result")
            elif new_status != CD_STATUS_CONFLICTED:
                raise _chain_invalid(f"{where} must not demote an accepted decision")
        elif previous_status == CD_STATUS_CONFLICTED:
            if new_status != CD_STATUS_CONFLICTED:
                raise _chain_invalid(f"{where} must not outvote a conflicted decision")
        hop_moment = payload[CP_MOMENT]
        if previous_moment is not None and hop_moment < previous_moment:
            raise _chain_invalid(f"{where} moment must not be earlier than its predecessor")
        if hop_moment > moment:
            raise _chain_invalid(f"{where} moment must not be later than the verification moment")
        issuer = payload[VD_ISSUER]
        key_version = payload[KEY_VERSION]
        for policy_index in (index, height):
            allowed = validated_policies[policy_index][CD_SITES].get(issuer)
            if allowed is None or key_version not in allowed:
                raise _chain_invalid(f"{where} issuer and key version are not authorized by the "
                    + ("previous" if policy_index == index else "new") + " policy")
        entry = _usable_checkpoint_key(validated_keyring, issuer, key_version, hop_moment)
        _usable_checkpoint_key(validated_keyring, issuer, key_version, moment)
        expected_signature = hmac.new(bytes.fromhex(entry[SECRET]), _checkpoint_compact(payload), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected_signature, signature):
            raise AuthenticationError(f"decision chain {where} signature does not match")
        previous_bytes = hop
        previous_certificates = certificates
        previous_status = new_status
        previous_common = new_common
        previous_moment = hop_moment
        head_digest = hashlib.sha256(hop).hexdigest()
        status = new_status
    return {
        SC_HEIGHT: len(successors),
        SC_HEAD_DIGEST: head_digest,
        SC_POLICY_VERSION: validated_policies[-1][VERSION],
        SC_ROOT_DIGEST: root_digest,
        STATUS: status,
        VERSION: DECISION_CHAIN_VERSION,
    }
```

