            if new_common != prev_common:
                raise ValueError("an accepted decision must keep its common result")
        elif new_status != CD_STATUS_CONFLICTED:
            raise ValueError("an accepted decision must not be demoted")
    elif prev_status == CD_STATUS_CONFLICTED and new_status != CD_STATUS_CONFLICTED:
        raise ValueError("a conflicted decision must not be outvoted")
    entry = _usable_checkpoint_key(validated_keyring, issuer, version, issue_moment)
    payload = {
        SC_DECISION: json.loads(new_packet),   # embed as nested object
        SC_EVIDENCE_DELTA: delta,
        SC_HEIGHT: height,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: issue_moment,
        CD_POLICY_DIGEST: _chain_policy_digest(validated_new),
        SC_PREDECESSOR_DIGEST: hashlib.sha256(predecessor).hexdigest(),
        SC_PREVIOUS_POLICY_DIGEST: _chain_policy_digest(validated_previous),
        SC_ROOT_DIGEST: root_digest,
        VERSION: DECISION_CHAIN_VERSION,
    }
    signature = hmac.new(bytes.fromhex(entry[SECRET]), _checkpoint_compact(payload), hashlib.sha256).hexdigest()
    return _checkpoint_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})
```

